) values
  (1, 'chanel-coco-mademoiselle', 'CHANEL', 'Coco Mademoiselle', 'Kadın', 'Oryantal', 'Coco Mademoiselle, taze portakalın kıvılcımıyla açılır; ardından gül ve yaseminin zarif dansı gelir. Alt notalardaki paçuli ve vanilya, kokuyu uzun saatler boyunca sıcak ve çekici tutar. Gün içinden akşama uzanan, özgür ve kendinden emin bir kadın imzasıdır.', 6850, 5790, ARRAY['https://images.unsplash.com/photo-1541643600914-78b084683601?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1619994403073-2cec844b8e63?auto=format&fit=crop&w=900&q=85'], 4.8, 133, 13, ARRAY[30, 50, 100], ARRAY['Portakal', 'Bergamot', 'Portakal çiçeği'], ARRAY['Türk gülü', 'Yasemin', 'Mimoza'], ARRAY['Paçuli', 'Beyaz misk', 'Vanilya', 'Vetiver'], false, true, true),
  (2, 'dior-sauvage-elixir', 'DIOR', 'Sauvage Elixir', 'Erkek', 'Oryantal', 'Sauvage Elixir, lavanta ve baharatın yoğun birleşimiyle açılan güçlü bir erkek karakteridir. Grapefruit ferahlığı, tarçın ve hindistan cevizinin sıcaklığıyla buluşur; amber ve odunsu taban ise kalıcı bir iz bırakır. Cesur, karizmatik ve unutulmaz bir imza arayanlar için.', 7290, 6490, ARRAY['/images/dior-sauvage.jpg', '/images/erkek-hero.jpg'], 4.8, 142, 14, ARRAY[30, 50, 100], ARRAY['Greyfurt', 'Elemi', 'Lavanta'], ARRAY['Tarçın', 'Hindistan cevizi', 'Lavanta absolute'], ARRAY['Amber', 'Licorice', 'Sandal ağacı', 'Paçuli'], false, true, true),
  (3, 'ysl-libre-intense', 'YVES SAINT LAURENT', 'Libre Intense', 'Kadın', 'Çiçeksi', 'Libre Intense, lavanta ve portakal çiçeğinin özgür ruhunu daha derin, daha tutkulu bir yoruma taşır. Madagaskar vanilyası ve amberwood, kokuyu kadifemsi ve kalıcı kılar. Hem gündüz zarafetini hem gece çekiciliğini taşıyan modern bir klasik.', 6490, 5490, ARRAY['https://images.unsplash.com/photo-1619994403073-2cec844b8e63?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1615634260167-c8cdede054de?auto=format&fit=crop&w=900&q=85'], 4.8, 151, 15, ARRAY[30, 50, 100], ARRAY['Lavanta', 'Mandarin', 'Bergamot'], ARRAY['Portakal çiçeği', 'Yasemin', 'Lavandin'], ARRAY['Madagaskar vanilyası', 'Amberwood', 'Misk', 'Sedir'], false, true, true),
  (4, 'tom-ford-ombre-leather', 'TOM FORD', 'Ombré Leather', 'Unisex', 'Odunsu', 'Ombré Leather, çöl rüzgârını andıran deri notasıyla açılır; yasemin ve ylang-ylang yumuşak bir çiçek dokunuşu ekler. Siyah biberin keskinliği, alt notalardaki yosun ve kehribarla dengelenir. Cinsiyetsiz, güçlü ve sofistike bir karakter kokusu.', 8990, 7790, ARRAY['https://images.unsplash.com/photo-1592945403244-b3fbafd7f539?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1523293182086-7651a899d37f?auto=format&fit=crop&w=900&q=85'], 4.8, 160, 16, ARRAY[30, 50, 100], ARRAY['Kardamon', 'Pembe biber'], ARRAY['Yasemin sambac', 'Deri', 'Ylang-ylang'], ARRAY['Yosun', 'Kehribar', 'Odunsu akorlar'], false, true, true),
  (5, 'armani-acqua-di-gio', 'GIORGIO ARMANI', 'Acqua di Giò', 'Erkek', 'Meyveli', 'Acqua di Giò, Ege’nin tuzlu esintisini limon ve bergamotla buluşturur. Deniz notaları ve yeşil taze yapraklar, jasmin ve gülün hafif dokunuşuyla yumuşar. Sedir ve misk, ferahlığı tüm güne yayar. Klasik, temiz ve zamansız bir erkek ferahlığı.', 5990, 5190, ARRAY['https://images.unsplash.com/photo-1615634260167-c8cdede054de?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1541643600914-78b084683601?auto=format&fit=crop&w=900&q=85'], 4.8, 169, 17, ARRAY[30, 50, 100], ARRAY['Limon', 'Bergamot', 'Neroli'], ARRAY['Deniz notaları', 'Yasemin', 'Şeftali'], ARRAY['Beyaz misk', 'Sedir', 'Paçuli'], false, true, true),
  (6, 'lancome-la-vie-est-belle', 'LANCÔME', 'La Vie Est Belle', 'Kadın', 'Meyveli', 'La Vie Est Belle, siyah frenk üzümü ve armutun tatlı kıvılcımıyla başlar; iris ve yasemin kalbinde zarif bir çiçek demeti sunar. Pralin ve vanilya alt notaları, kokuyu gülümseten, sıcak ve unutulmaz kılar. Mutluluğu ve zarafeti bir arada taşıyan ikonik bir kadın parfümü.', 6250, 5350, ARRAY['https://images.unsplash.com/photo-1523293182086-7651a899d37f?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1594035910387-fea47794261f?auto=format&fit=crop&w=900&q=85'], 4.8, 178, 18, ARRAY[30, 50, 100], ARRAY['Siyah frenk üzümü', 'Armut'], ARRAY['Iris', 'Yasemin', 'Portakal çiçeği'], ARRAY['Pralin', 'Vanilya', 'Tonka fasulyesi', 'Paçuli'], false, true, true),
  (7, 'prada-paradoxe', 'PRADA', 'Paradoxe', 'Kadın', 'Çiçeksi', 'Paradoxe, bergamot ve armutun kristal netliğiyle açılır; neroli ve yasemin kalbinde ışıldayan bir çiçek demeti yaratır. Amber ve beyaz misk, kokuyu modern, temiz ve uzun ömürlü kılar. Zıtlıkların uyumunu seven, çağdaş kadınlar için.', 6790, 5990, ARRAY['https://images.unsplash.com/photo-1619994403073-2cec844b8e63?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1615634260167-c8cdede054de?auto=format&fit=crop&w=900&q=85'], 4.8, 187, 19, ARRAY[30, 50, 100], ARRAY['Bergamot', 'Armut', 'Mercan'], ARRAY['Neroli', 'Yasemin', 'Turuncu çiçek'], ARRAY['Amber', 'Beyaz misk', 'Benzoin'], false, false, true),
  (8, 'gucci-guilty-elixir', 'GUCCI', 'Guilty Elixir', 'Erkek', 'Odunsu', 'Guilty Elixir, aromatik lavanta ve baharatlı üst notalarla cesur bir giriş yapar. Gül ve paçuli kalbinde karanlık bir çekicilik; amber ve odunsu taban ise geceye yayılan kalıcı bir güç bırakır. Tutkulu ve sınır tanımayan bir erkek imzası.', 7590, 6890, ARRAY['https://images.unsplash.com/photo-1615634260167-c8cdede054de?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1541643600914-78b084683601?auto=format&fit=crop&w=900&q=85'], 4.8, 196, 20, ARRAY[30, 50, 100], ARRAY['Lavanta', 'Limon', 'Pembe biber'], ARRAY['Gül', 'Paçuli', 'Fesleğen'], ARRAY['Amber', 'Sedir', 'Tonka', 'Misk'], true, false, true),
  (9, 'burberry-goddess', 'BURBERRY', 'Goddess', 'Kadın', 'Oryantal', 'Goddess, vanilyanın üç katmanlı yorumuyla öne çıkar: taze, kremsi ve fırınlanmış sıcaklık bir arada. Lavanta ve kakao, kokuya derin ve lüks bir dokunuş katar. Güçlü, kadınsı ve çağdaş bir tanrıça enerjisi arayanlar için.', 6190, 5590, ARRAY['https://images.unsplash.com/photo-1541643600914-78b084683601?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1619994403073-2cec844b8e63?auto=format&fit=crop&w=900&q=85'], 4.8, 205, 21, ARRAY[30, 50, 100], ARRAY['Lavanta', 'Limon'], ARRAY['Kakao', 'Lavanta absolute'], ARRAY['Vanilya', 'Amber', 'Misk'], true, false, true),
  (10, 'givenchy-gentleman-reserve', 'GIVENCHY', 'Gentleman Réserve Privée', 'Erkek', 'Oryantal', 'Gentleman Réserve Privée, iris ve kestane’nin nadir birleşimiyle sofistike bir giriş yapar. Viski ve vanilyanın sıcaklığı, odunsu tabanla tamamlanır. Zarif, olgun ve özel günlere yakışan bir centilmen kokusu.', 6490, 5790, ARRAY['https://images.unsplash.com/photo-1592945403244-b3fbafd7f539?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1523293182086-7651a899d37f?auto=format&fit=crop&w=900&q=85'], 4.8, 214, 22, ARRAY[30, 50, 100], ARRAY['Bergamot', 'Armut'], ARRAY['Iris', 'Kestane', 'Gül'], ARRAY['Viski', 'Vanilya', 'Sedir', 'Amber'], true, false, true),
  (11, 'calvin-klein-everyone', 'CALVIN KLEIN', 'CK Everyone', 'Unisex', 'Meyveli', 'CK Everyone, portakal ve yuzu’nun parlak ferahlığıyla herkese hitap eden temiz bir koku sunar. Mavi lotus ve misk, hafif ve modern bir his bırakır. Günlük kullanıma uygun, unisex ve kolay sevilen bir seçim.', 4290, 3690, ARRAY['https://images.unsplash.com/photo-1523293182086-7651a899d37f?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1594035910387-fea47794261f?auto=format&fit=crop&w=900&q=85'], 4.8, 223, 0, ARRAY[30, 50, 100], ARRAY['Portakal', 'Yuzu', 'Bergamot'], ARRAY['Mavi lotus', 'Fesleğen'], ARRAY['Misk', 'Amberwood', 'Sedir'], true, false, true),
  (12, 'chanel-bleu-de-chanel', 'CHANEL', 'Bleu de Chanel', 'Erkek', 'Odunsu', 'Bleu de Chanel, greyfurt ve limonun ferah kıvılcımıyla başlar; zencefil ve nane ile enerjik bir orta nota buluşur. Sedir, sandal ve labdanum, kokuyu zarif ve kalıcı bir erkek imzasına dönüştürür. Hem ofis hem akşam için kusursuz bir klasik.', 7450, 6690, ARRAY['https://images.unsplash.com/photo-1615634260167-c8cdede054de?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1541643600914-78b084683601?auto=format&fit=crop&w=900&q=85'], 4.8, 232, 24, ARRAY[30, 50, 100], ARRAY['Greyfurt', 'Limon', 'Nane', 'Pembe biber'], ARRAY['Zencefil', 'Iso E Super', 'Nutmeg'], ARRAY['Sedir', 'Sandal ağacı', 'Labdanum', 'Beyaz misk'], false, true, true),
  (13, 'burberry-hero', 'BURBERRY', 'Hero', 'Erkek', 'Odunsu', 'Hero, bergamot ve siyah biberin canlı açılışıyla dikkat çeker. Üç farklı sedir ağacı kalbinde güçlü ve modern bir odunsu karakter yaratır. Cesur, net ve çağdaş bir erkeklik ifadesi arayanlar için Burberry’nin güçlü yorumu.', 5890, 5290, ARRAY['https://images.unsplash.com/photo-1594035910387-fea47794261f?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1592945403244-b3fbafd7f539?auto=format&fit=crop&w=900&q=85'], 4.8, 241, 25, ARRAY[30, 50, 100], ARRAY['Bergamot', 'Siyah biber'], ARRAY['Atlas sediri', 'Virginia sediri', 'Himalaya sediri'], ARRAY['Vetiver', 'Amber', 'Misk'], false, false, true),
  (14, 'calvin-klein-eternity-men', 'CALVIN KLEIN', 'Eternity for Men', 'Erkek', 'Çiçeksi', 'Eternity for Men, lavanta ve mandalina ile taze bir giriş yapar; geranium ve adaçayı orta notada yeşil bir ferahlık sunar. Sedir ve sandal, kokuyu temiz ve zamansız kılar. Günlük kullanıma ideal, klasik ve güvenilir bir erkek parfümü.', 3990, 3490, ARRAY['https://images.unsplash.com/photo-1523293182086-7651a899d37f?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1594035910387-fea47794261f?auto=format&fit=crop&w=900&q=85'], 4.8, 250, 26, ARRAY[30, 50, 100], ARRAY['Lavanta', 'Mandalina', 'Limon'], ARRAY['Geranium', 'Adaçayı', 'Fesleğen', 'Jasmin'], ARRAY['Sedir', 'Sandal ağacı', 'Amber', 'Misk'], false, false, true),
  (15, 'paco-rabanne-1-million', 'PACO RABANNE', '1 Million', 'Erkek', 'Oryantal', '1 Million, greyfurt ve nane ile enerjik açılır; gül ve tarçın kalbinde gösterişli bir sıcaklık yaratır. Amber, deri ve odunsu notalar geceye yayılan çekici bir iz bırakır. Cesur, dikkat çekici ve partilere yakışan ikonik bir erkek kokusu.', 5690, 4990, ARRAY['https://images.unsplash.com/photo-1541643600914-78b084683601?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1619994403073-2cec844b8e63?auto=format&fit=crop&w=900&q=85'], 4.8, 259, 27, ARRAY[30, 50, 100], ARRAY['Greyfurt', 'Nane', 'Kan kaneli'], ARRAY['Gül', 'Tarçın', 'Baharatlı akorlar'], ARRAY['Amber', 'Deri', 'Beyaz odunlar', 'Paçuli'], false, true, true),
  (16, 'prada-luna-rossa', 'PRADA', 'Luna Rossa', 'Erkek', 'Meyveli', 'Luna Rossa, lavanta ve turuncu çiçeğin ferah birleşimiyle spor bir zarafet sunar. Adaçayı ve ambroxan, kokuyu modern ve dinamik kılar. Aktif yaşam tarzına uygun, temiz ve kalıcı bir erkek ferahlığı.', 6290, 5590, ARRAY['https://images.unsplash.com/photo-1619994403073-2cec844b8e63?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1615634260167-c8cdede054de?auto=format&fit=crop&w=900&q=85'], 4.8, 268, 28, ARRAY[30, 50, 100], ARRAY['Lavanta', 'Turuncu çiçek'], ARRAY['Adaçayı', 'Ambrette'], ARRAY['Ambroxan', 'Misk', 'Odunsu notalar'], false, false, true),
  (17, 'tom-ford-oud-wood', 'TOM FORD', 'Oud Wood', 'Erkek', 'Odunsu', 'Oud Wood, nadir oud ağacının dumanlı ve egzotik dokunuşunu gül ağacı ve kakule ile dengeler. Sandal ve vetiver alt notaları, kokuyu lüks, derin ve sofistike kılar. Niş zarafet arayanlar için Tom Ford’un efsanevi imzası.', 9490, 8490, ARRAY['https://images.unsplash.com/photo-1592945403244-b3fbafd7f539?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1523293182086-7651a899d37f?auto=format&fit=crop&w=900&q=85'], 4.8, 277, 29, ARRAY[30, 50, 100], ARRAY['Gül ağacı', 'Kakule', 'Pembe biber'], ARRAY['Oud', 'Sandal ağacı', 'Vetiver'], ARRAY['Tonka fasulyesi', 'Amber', 'Vanilya'], false, true, true),
  (18, 'ysl-y-edp', 'YVES SAINT LAURENT', 'Y Eau de Parfum', 'Erkek', 'Odunsu', 'Y EDP, elma ve zencefilin canlı kıvılcımıyla açılır; adaçayı ve lavanta orta notada ferah bir güç katar. Sedır ve tonka, kokuyu modern ve kararlı bir erkek karakterine dönüştürür. Hem gündüz hem gece için çok yönlü bir favori.', 6790, 5990, ARRAY['https://images.unsplash.com/photo-1594035910387-fea47794261f?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1592945403244-b3fbafd7f539?auto=format&fit=crop&w=900&q=85'], 4.8, 286, 30, ARRAY[30, 50, 100], ARRAY['Elma', 'Zencefil', 'Bergamot'], ARRAY['Adaçayı', 'Lavanta', 'Geranium'], ARRAY['Sedir', 'Tonka fasulyesi', 'Vetiver', 'Amberwood'], false, true, true),
  (19, 'valentino-uomo-born-in-roma', 'VALENTINO', 'Uomo Born in Roma', 'Erkek', 'Oryantal', 'Uomo Born in Roma, viyolet yaprağı ve tuzlu akorlarla modern bir açılış yapar. Vetiver ve mineral notalar, Roma’nın gece ruhunu yansıtır. Şık, genç ve şehirli bir erkek imajı için Valentino’nun çağdaş yorumu.', 6590, 5890, ARRAY['https://images.unsplash.com/photo-1615634260167-c8cdede054de?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1541643600914-78b084683601?auto=format&fit=crop&w=900&q=85'], 4.8, 295, 31, ARRAY[30, 50, 100], ARRAY['Viyolet yaprağı', 'Tuzlu akor'], ARRAY['Lavanta'], ARRAY['Vetiver', 'Mineral notalar'], false, false, true),
  (20, 'trussardi-uomo', 'TRUSSARDI', 'Uomo', 'Erkek', 'Odunsu', 'Trussardi Uomo, limon ve bergamotun ferah açılışıyla İtalyan zarafetini taşır. Lavanta ve geranium orta notada klasik bir erkeklik sunar; sedir ve amber ise kalıcı bir bitiş bırakır. Günlük kullanıma uygun, zarif ve erişilebilir bir seçim.', 4890, 4290, ARRAY['https://images.unsplash.com/photo-1523293182086-7651a899d37f?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1594035910387-fea47794261f?auto=format&fit=crop&w=900&q=85'], 4.8, 304, 32, ARRAY[30, 50, 100], ARRAY['Limon', 'Bergamot', 'Nane'], ARRAY['Lavanta', 'Geranium', 'Adaçayı'], ARRAY['Sedir', 'Amber', 'Misk', 'Tonka'], false, false, true),
  (21, 'philipp-plein-no-limits', 'PHILIPP PLEIN', 'No Limits', 'Erkek', 'Oryantal', 'No Limits, baharatlı ve meyveli üst notalarla iddialı bir giriş yapar. Deri ve amber kalbinde güçlü bir karakter; odunsu taban ise uzun süre hissedilen bir iz bırakır. Sınır tanımayan, gösterişli ve cesur bir gece kokusu.', 7190, 6490, ARRAY['https://images.unsplash.com/photo-1541643600914-78b084683601?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1619994403073-2cec844b8e63?auto=format&fit=crop&w=900&q=85'], 4.8, 313, 33, ARRAY[30, 50, 100], ARRAY['Turunçgil', 'Baharat', 'Elma'], ARRAY['Deri', 'Amber', 'Gül'], ARRAY['Sedir', 'Paçuli', 'Misk', 'Vanilya'], true, false, true),
  (22, 'clive-christian-no1-men', 'CLIVE CHRISTIAN', 'No.1 Men', 'Erkek', 'Oryantal', 'No.1 Men, nadir baharatlar ve egzotik çiçeklerin lüks birleşimidir. Gül, yasemin ve vanilya, odunsu ve amberli bir tabanla taçlanır. Kraliyet zarafetini andıran, koleksiyon değeri taşıyan ultra premium bir erkek parfümü.', 12990, 11490, ARRAY['https://images.unsplash.com/photo-1592945403244-b3fbafd7f539?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1523293182086-7651a899d37f?auto=format&fit=crop&w=900&q=85'], 4.8, 322, 34, ARRAY[30, 50, 100], ARRAY['Bergamot', 'Limon', 'Kakule', 'Hindistan cevizi'], ARRAY['Gül', 'Yasemin', 'Iris', 'Baharatlı akorlar'], ARRAY['Vanilya', 'Amber', 'Sandal ağacı', 'Misk'], false, false, true),
  (23, 'kilian-black-phantom', 'KILIAN', 'Black Phantom', 'Erkek', 'Oryantal', 'Black Phantom, rom ve şeker kamışının karanlık tatlılığıyla açılır; kahve ve bitter çikolata kalbinde derin bir çekicilik yaratır. Sandal ve vanilya, kokuyu kadifemsi ve bağımlılık yapan bir gece imzasına dönüştürür. Lüks ve gizemli bir seçim.', 10990, 9790, ARRAY['https://images.unsplash.com/photo-1594035910387-fea47794261f?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1592945403244-b3fbafd7f539?auto=format&fit=crop&w=900&q=85'], 4.8, 331, 35, ARRAY[30, 50, 100], ARRAY['Rom', 'Şeker kamışı'], ARRAY['Kahve', 'Bitter çikolata', 'Sandal ağacı'], ARRAY['Vanilya', 'Şeker', 'Amber'], false, false, true),
  (24, 'mfk-gentle-fluidity-silver', 'MAISON FRANCIS KURKDJIAN', 'Gentle Fluidity Silver', 'Erkek', 'Odunsu', 'Gentle Fluidity Silver, ardıç ve hindistan cevizinin kristal netliğiyle açılır; amberwood ve misk modern bir akışkanlık katar. Minimal ama güçlü, temiz ve sofistike bir niş imza. Zarif sadelik arayanlar için MFK’nın ustalık işi.', 9890, 8890, ARRAY['https://images.unsplash.com/photo-1619994403073-2cec844b8e63?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1615634260167-c8cdede054de?auto=format&fit=crop&w=900&q=85'], 4.8, 340, 36, ARRAY[30, 50, 100], ARRAY['Ardıç', 'Hindistan cevizi'], ARRAY['Amberwood', 'Iso E Super'], ARRAY['Misk', 'Odunsu akorlar'], false, false, true),
  (25, 'marfa-memoir', 'MARFA', 'Memoir', 'Erkek', 'Odunsu', 'Memoir, çölün kuru esintisini andıran odunsu ve aromatik notalarla açılır. Deri ve amber dokunuşları, kokuya sıcak bir derinlik katar. Modern, karakterli ve az bilinen bir seçim arayanlar için Bee’nin özel önerisi.', 8290, 7490, ARRAY['https://images.unsplash.com/photo-1615634260167-c8cdede054de?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1541643600914-78b084683601?auto=format&fit=crop&w=900&q=85'], 4.8, 349, 37, ARRAY[30, 50, 100], ARRAY['Bergamot', 'Aromatik otlar'], ARRAY['Deri', 'Lavanta', 'Sedir'], ARRAY['Amber', 'Misk', 'Vetiver'], true, false, true),
  (26, 'opulent-shaik-gold', 'OPULENT SHAIK', 'Gold Edition', 'Erkek', 'Oryantal', 'Gold Edition, turunçgil ve baharatın altın ışıltısıyla başlar; gül ve oud kalbinde Doğu’nun lüksünü yansıtır. Amber ve vanilya, kokuyu zengin ve kalıcı kılar. Gösterişli, sıcak ve unutulmaz bir oryantal erkek imzası.', 8790, 7890, ARRAY['https://images.unsplash.com/photo-1541643600914-78b084683601?auto=format&fit=crop&w=900&q=85', 'https://images.unsplash.com/photo-1619994403073-2cec844b8e63?auto=format&fit=crop&w=900&q=85'], 4.8, 358, 38, ARRAY[30, 50, 100], ARRAY['Bergamot', 'Baharat', 'Turunçgil'], ARRAY['Gül', 'Oud', 'Yasemin'], ARRAY['Amber', 'Vanilya', 'Misk', 'Sedir'], true, false, true)
